// aceitação sempre abre uma partida entre as duas pessoas certas.
const desafiosPendentes = new Map();

const { Server: SocketServer } = require('socket.io');
const jogadoresOnline = {};
const ioduelo = new SocketServer(server, { cors: { origin: '*' }, path: '/duelo/socket.io' });

function jogadorEstaEmPartida(socketId) {
  return Object.values(duelSalas).some(sala => sala.j.some(jogador => jogador.id === socketId));
}

function tirarDaFila(socketId) {
  if (duelEsperando && duelEsperando.socket.id === socketId) duelEsperando = null;
}

function iniciarDueloDireto(socketA, jogadorA, socketB, jogadorB) {
  const sid = 'duelo_' + Date.now();
  const perguntasA = shuffleArray(perguntasDuelo[jogadorA.lang] || perguntasDuelo.pt).slice(0, 10);
  const perguntasB = shuffleArray(perguntasDuelo[jogadorB.lang] || perguntasDuelo.pt).slice(0, 10);
  socketA.join(sid);
  socketB.join(sid);
  duelSalas[sid] = {
    j: [
      { id: socketA.id, nome: jogadorA.nome, lang: jogadorA.lang, pts: 0, resp: false, foto: jogadorA.foto || null, perguntas: perguntasA },
      { id: socketB.id, nome: jogadorB.nome, lang: jogadorB.lang, pts: 0, resp: false, foto: jogadorB.foto || null, perguntas: perguntasB }
    ],
    qi: 0, t: 15, timer: null, advancing: false
  };
  socketA.emit('inicioJogo', { salaId: sid, oponente: jogadorB.nome, fotoOponente: jogadorB.foto || null, pergunta: perguntasA[0] });
  socketB.emit('inicioJogo', { salaId: sid, oponente: jogadorA.nome, fotoOponente: jogadorA.foto || null, pergunta: perguntasB[0] });
  duelTimer(sid);
}

ioduelo.on('connection', (socket) => {
  socket.on('registrarJogador', (d = {}) => {
    const nome = String(d.nome || '').trim();
    if (!nome) return;
    jogadoresOnline[socket.id] = { nome, foto: d.foto || null, socketId: socket.id, lang: d.idioma || 'pt' };
  });

  socket.on('jogarComBot', (d) => {
    const lang = d.idioma || 'pt';
    const nome = d.nome || 'Jogador';
    const foto = d.foto || null;
    // O bot não entra nesta lista: ela deve conter apenas pessoas reais.
    jogadoresOnline[socket.id] = { nome, foto, socketId: socket.id, lang };
    const sid = 'bot_' + Date.now();
    const perguntas = shuffleArray(perguntasDuelo[lang] || perguntasDuelo.pt).slice(0, 10);
    socket.join(sid);
    duelSalas[sid] = { j:[{id:socket.id,nome,lang,pts:0,resp:false,foto,perguntas},{id:'bot_'+sid,nome:'Bot Bíblico',lang,pts:0,resp:false,bot:true,perguntas}], qi:0, t:15, timer:null, advancing:false };
    socket.emit('inicioJogo', {salaId:sid, oponente:'Bot Bíblico', pergunta:perguntas[0]});
    duelTimer(sid);
  });
  socket.on('procurarPartida', (d) => {
    const lang = d.idioma || 'pt';
    const fotoRaw = d.foto || null; const foto = fotoRaw && fotoRaw.startsWith('http') ? fotoRaw : (fotoRaw && fotoRaw.length < 5000 ? fotoRaw : null);
    const nome = d.nome || 'Jogador';
    jogadoresOnline[socket.id] = { nome, foto, socketId: socket.id, lang };
    if (!duelEsperando) {
      duelEsperando = { socket, nome, lang, foto };
      socket.emit('status', 'Aguardando...');
    } else {
      if (duelEsperando.socket.id === socket.id) {
        socket.emit('status', 'Aguardando um adversário real...');
        return;
      }
      const op = duelEsperando; duelEsperando = null;
      const sid = 'duelo_' + Date.now();
      socket.join(sid); op.socket.join(sid);
      const p1 = shuffleArray(perguntasDuelo[lang] || perguntasDuelo.pt).slice(0,10);
      const p2 = shuffleArray(perguntasDuelo[op.lang] || perguntasDuelo.pt).slice(0,10);
      duelSalas[sid] = { j:[{id:socket.id,nome,lang,pts:0,resp:false,foto,perguntas:p1},{id:op.socket.id,nome:op.nome,lang:op.lang,pts:0,resp:false,foto:op.foto||null,perguntas:p2}], qi:0, t:15, timer:null, advancing:false };
      socket.emit('inicioJogo', {salaId:sid, oponente:op.nome, fotoOponente:op.foto||null, pergunta:p1[0]});
      op.socket.emit('inicioJogo', {salaId:sid, oponente:nome, fotoOponente:foto||null, pergunta:p2[0]});
      duelTimer(sid);
    }
  });
  socket.on('chatDuelo',(d)=>{ const sala=duelSalas[d.salaId]; if(!sala) return; socket.to(d.salaId).emit('chatDuelo',{msg:d.msg,nome:d.nome}); });
  socket.on('enviarResposta', (d) => {
    const sala = duelSalas[d.salaId]; if (!sala) return;
    if (sala.advancing) return;
    const j = sala.j.find(x => x.id === socket.id);
    if (j && !j.resp) {
      j.resp = true;
      const p = (j.perguntas||perguntasDuelo[j.lang]||perguntasDuelo.pt)[sala.qi];
      const acertou = d.escolha === p.c;
      if (acertou) j.pts += 100 + (sala.t * 5);
      const op = sala.j.find(x => x.id !== socket.id);
      if (op) ioduelo.to(op.id).emit('oponenteRespondeu');
      // Uma resposta correta vence a rodada: ambos avançam sem esperar o cronómetro.
      if (acertou) {
        sala.advancing = true;
        clearInterval(sala.timer);
        ioduelo.to(d.salaId).emit('rodadaEncerrada', { vencedor: j.nome });
        setTimeout(() => {
          const atual = duelSalas[d.salaId];
          if (!atual) return;
          atual.advancing = false;
          duelProxima(d.salaId);
        }, 850);
      } else if (sala.j.every(x => x.resp)) {
        sala.advancing = true;
        clearInterval(sala.timer);
        setTimeout(() => {
          const atual = duelSalas[d.salaId];
          if (!atual) return;
          atual.advancing = false;
          duelProxima(d.salaId);
        }, 850);
      }
    }
  });


  socket.on('chatMsg', (d) => {
    const { salaId, msg, nome } = d;
    if (duelSalas[salaId]) {
      ioduelo.to(salaId).emit('chatMsg', { nome, msg });
    }
  });

  socket.on('desafiarJogador', (d = {}) => {
    const desafiante = jogadoresOnline[socket.id];
    const alvo = Object.values(jogadoresOnline).find(j => j.nome === d.para);
    if (!desafiante || !alvo || alvo.socketId === socket.id || jogadorEstaEmPartida(socket.id) || jogadorEstaEmPartida(alvo.socketId)) {
      socket.emit('desafioIndisponivel');
      return;
    }
    desafiosPendentes.set(alvo.socketId, socket.id);
    ioduelo.to(alvo.socketId).emit('desafioRecebido', { nome: desafiante.nome, id: socket.id });
  });

  socket.on('aceitarDesafio', (d = {}) => {
    const desafianteId = d.deId || desafiosPendentes.get(socket.id);
    if (!desafianteId || desafiosPendentes.get(socket.id) !== desafianteId) {
      socket.emit('desafioIndisponivel');
      return;
    }
    const desafiante = jogadoresOnline[desafianteId];
    const convidado = jogadoresOnline[socket.id];
    const socketDesafiante = ioduelo.sockets.sockets.get(desafianteId);
    desafiosPendentes.delete(socket.id);
    if (!desafiante || !convidado || !socketDesafiante || jogadorEstaEmPartida(desafianteId) || jogadorEstaEmPartida(socket.id)) {
      socket.emit('desafioIndisponivel');
      return;
    }
    tirarDaFila(desafianteId);
    tirarDaFila(socket.id);
    socketDesafiante.emit('desafioAceite', { nome: convidado.nome });
    iniciarDueloDireto(socketDesafiante, desafiante, socket, convidado);
  });

  socket.on('disconnect', () => {
    delete jogadoresOnline[socket.id];
    desafiosPendentes.delete(socket.id);
    for (const [convidadoId, desafianteId] of desafiosPendentes.entries()) {
      if (desafianteId === socket.id) desafiosPendentes.delete(convidadoId);
    }

    if (duelEsperando && duelEsperando.socket.id === socket.id) duelEsperando = null;
    for (const [sid, sala] of Object.entries(duelSalas)) {
      if (sala.j.find(x => x.id === socket.id)) {
        clearInterval(sala.timer);
        ioduelo.to(sid).emit('oponenteSaiu');
        // Uma partida interrompida não entra no ranking e deve apenas limpar a sala.
        delete duelSalas[sid];
      }
    }
  });
});

function duelTimer(sid) {
  const sala = duelSalas[sid]; if (!sala) return;
  sala.t = 15;
  sala.timer = setInterval(() => {
    sala.t--;
    ioduelo.to(sid).emit('atualizarTimer', sala.t);
    if (sala.t <= 0) { clearInterval(sala.timer); duelProxima(sid); }
  }, 1000);
  duelBotResponder(sid, sala.qi);
}

function duelBotResponder(sid, questionIndex) {
  const sala = duelSalas[sid]; if (!sala) return;
  const bot = sala.j.find(j => j.bot); if (!bot) return;
  // Dá sempre pelo menos 7 segundos à pessoa antes de o Bot responder.
  // Depois varia até 10 segundos para a partida não parecer mecânica.
  const delay = 7000 + Math.floor(Math.random() * 3000);
  setTimeout(() => {
    const atual = duelSalas[sid];
    if (!atual || atual.qi !== questionIndex || atual.advancing || bot.resp) return;
    bot.resp = true;
    const acertou = Math.random() < 0.58;
    if (acertou) {
      bot.pts += 100 + (atual.t * 5);
      atual.advancing = true;
      clearInterval(atual.timer);
      ioduelo.to(sid).emit('oponenteRespondeu');
      ioduelo.to(sid).emit('rodadaEncerrada', { vencedor: bot.nome });
      setTimeout(() => { const salaNova = duelSalas[sid]; if (!salaNova) return; salaNova.advancing=false; duelProxima(sid); }, 850);
    } else if (atual.j.every(j => j.resp)) {
      atual.advancing = true;
      clearInterval(atual.timer);
      setTimeout(() => { const salaNova = duelSalas[sid]; if (!salaNova) return; salaNova.advancing=false; duelProxima(sid); }, 850);
    }
  }, delay);
}

function duelProxima(sid) {
  const sala = duelSalas[sid]; if (!sala) return;
  clearInterval(sala.timer);
  sala.qi++; sala.j.forEach(j => j.resp = false);
  if (sala.qi < 10) {
    sala.j.forEach(j => {
      const p = (j.perguntas||perguntasDuelo[j.lang]||perguntasDuelo.pt)[sala.qi];
      ioduelo.to(j.id).emit('novaPergunta', {pergunta:p});
    });
    duelTimer(sid);
  } else {
    const resultado = sala.j.map(j=>({nome:j.nome,pontos:j.pts,foto:j.foto||null}));
    ioduelo.to(sid).emit('fimJogo', resultado);
    // Actualizar ranking semanal
    resultado.forEach(j => {
      if (!rankingSemanal[j.nome]) rankingSemanal[j.nome] = {pontos:0,foto:null};
      rankingSemanal[j.nome].pontos += j.pontos;
      if(j.foto) rankingSemanal[j.nome].foto = j.foto;
    });

    resultado.forEach(async j => {
      try {
        await pool.query('INSERT INTO duelo_ranking (nome,pontos,foto) VALUES ($1,$2,$3) ON CONFLICT (nome) DO UPDATE SET pontos=duelo_ranking.pontos+$2, foto=COALESCE($3,duelo_ranking.foto), updated_at=NOW()', [j.nome,j.pontos,j.foto||null]);
      } catch(e){}
    });
    delete duelSalas[sid];
  }
}
// ========== FIM DUELO BIBLICO ==========

// ========== RANKING SEMANAL PIX ==========
let rankingSemanal = {};
let pixAtivo = false;
let pixValor = 'R$ 10,00';

// Rota para ver ranking

app.get('/api/duelo/online-jogadores', (req, res) => {
  const jogadores = Object.values(jogadoresOnline).map(j => ({ nome: j.nome, foto: j.foto || null }));
  res.json({ jogadores });
});

app.get('/api/duelo/online', (req, res) => {
  // Conta conexões humanas ativas (em partida ou à espera), nunca o Bot Bíblico.
  const online = Object.keys(jogadoresOnline).length;
  res.json({ online });
});


app.get('/api/duelo/ranking', async (req, res) => {
  try {
    const r = await pool.query(`SELECT nome, pontos, foto,
      ROW_NUMBER() OVER (ORDER BY pontos DESC, updated_at ASC) AS posicao
      FROM duelo_ranking ORDER BY pontos DESC, updated_at ASC LIMIT 10`);
    res.json({ ranking: r.rows, pix: pixValor });
  } catch(e) {
    res.json({ ranking: [], pix: pixValor });
  }
});

// Rota admin para activar/desactivar PIX
app.post('/api/duelo/pix', (req, res) => {
  const { token, ativo, valor } = req.body;
  if (!process.env.ADMIN_SECRET || token !== process.env.ADMIN_SECRET) {
    return res.status(401).json({ error: 'Nao autorizado' });
  }
  pixAtivo = ativo;
  if (valor) pixValor = valor;
  // Zerar ranking ao activar nova semana
  if (ativo) rankingSemanal = {};
  res.json({ ok: true, pixAtivo, pixValor });
});

// Rota para zerar ranking manualmente
app.post('/api/duelo/zerar', (req, res) => {
  const { token } = req.body;
  if (!process.env.ADMIN_SECRET || token !== process.env.ADMIN_SECRET) {
    return res.status(401).json({ error: 'Nao autorizado' });
  }
  rankingSemanal = {};
  res.json({ ok: true, msg: 'Ranking zerado!' });
});
// ========== FIM RANKING SEMANAL PIX ==========
